from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        # Parse hint
        op_part, cond_part = current_hint.split(' ', 1)

        # Define compute_value
        def compute_value(op, row, col):
            if op == 'sum':
                return row + col
            elif op == 'product':
                return row * col
            elif op == 'difference':
                return abs(row - col)
            else:
                raise ValueError(f"Unknown operation: {op}")

        # Parse condition into a function
        def parse_condition(cond_str):
            parts = cond_str.split()
            if parts[0] == 'is':
                if parts[1] == 'less':
                    v = int(parts[3])
                    return lambda x: x < v
                elif parts[1] == 'greater':
                    v = int(parts[3])
                    return lambda x: x > v
                elif parts[1] == 'even':
                    return lambda x: x % 2 == 0
                elif parts[1] == 'odd':
                    return lambda x: x % 2 != 0
                elif parts[1] == 'between':
                    v1 = int(parts[2])
                    v2 = int(parts[4])
                    return lambda x: v1 <= x <= v2
                else:
                    raise ValueError("Unknown condition")
            elif parts[0] == 'contains':
                if parts[1] == 'digit':
                    digit = parts[2]
                    return lambda x: str(x).find(digit) != -1
                else:
                    raise ValueError("Invalid contains condition")
            else:
                raise ValueError("Invalid condition format")

        cond_func = parse_condition(cond_part)

        # Collect valid positions
        rows = len(current_grid)
        cols = len(current_grid[0]) if rows else 0
        valid_positions = []
        for r in range(rows):
            for c in range(cols):
                row = r + 1
                col = c + 1
                if current_grid[r][c] != 0:
                    continue
                val = compute_value(op_part, row, col)
                if cond_func(val):
                    valid_positions.append((row, col))

        # Determine priority based on player
        if player_idx == 1:
            def priority(pos):
                r, c = pos
                if c == 1 or c == cols:
                    middle_row = (rows + 1) // 2
                    distance = abs(r - middle_row)
                    return 100 - distance
                else:
                    middle_row = (rows + 1) // 2
                    middle_col = (cols + 1) // 2
                    dr = abs(r - middle_row)
                    dc = abs(c - middle_col)
                    return 50 - (dr + dc)
        else:
            def priority(pos):
                r, c = pos
                if r == 1 or r == rows:
                    middle_col = (cols + 1) // 2
                    distance = abs(c - middle_col)
                    return 100 - distance
                else:
                    middle_row = (rows + 1) // 2
                    middle_col = (cols + 1) // 2
                    dr = abs(r - middle_row)
                    dc = abs(c - middle_col)
                    return 50 - (dr + dc)

        # Sort and select
        sorted_positions = sorted(valid_positions, key=lambda p: -priority(p))
        position_selected = sorted_positions[0] if sorted_positions else (0, 0)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

