                    candidates.append((r, c))

        best_pos = None
        min_distance = float('inf')
        for (r, c) in candidates:
            current_distance = abs(r - center_r) + abs(c - center_c)
            if best_pos is None:
                best_pos = (r, c)
                min_distance = current_distance
