from pydantic import BaseModel
from typing import List, Optional, Dict, Any
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy
from collections import deque

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        def has_left_right_connection(grid, player):
            rows = len(grid)
            cols = len(grid[0]) if rows else 0
            visited = [[False for _ in range(cols)] for _ in range(rows)]
            q = deque()
            for r in range(rows):
                if grid[r][0] == player:
                    visited[r][0] = True
                    q.append((r, 0))
            while q:
                r, c = q.popleft()
                if c == cols - 1:
                    return True
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == player:
                                visited[nr][nc] = True
                                q.append((nr, nc))
            return False

        def has_top_bottom_connection(grid, player):
            rows = len(grid)
            cols = len(grid[0]) if rows else 0
            visited = [[False for _ in range(cols)] for _ in range(rows)]
            q = deque()
            for c in range(cols):
                if grid[0][c] == player:
                    visited[0][c] = True
                    q.append((0, c))
            while q:
                r, c = q.popleft()
                if r == rows - 1:
                    return True
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == player:
                                visited[nr][nc] = True
                                q.append((nr, nc))
            return False

        def parse_condition(condition_str):
            tokens = condition_str.split()
            if tokens[0] == 'is':
                if tokens[1] == 'less':
                    return ('less than', int(tokens[3]))
                elif tokens[1] == 'greater':
                    return ('greater than', int(tokens[3]))
                elif tokens[1] == 'even':
                    return ('even', None)
                elif tokens[1] == 'odd':
                    return ('odd', None)
                elif tokens[1] == 'between':
                    v1 = int(tokens[2])
                    v2 = int(tokens[4])
                    return ('between', (v1, v2))
            elif tokens[0] == 'contains':
                if tokens[1] == 'digit':
                    return ('contains digit', (int(tokens[2]),))
            raise ValueError('Invalid condition')

        def parse_hint(hint_str):
            parts = hint_str.split()
            operation = parts[0]
            condition_str = ' '.join(parts[1:])
            cond_type, values = parse_condition(condition_str)
            return operation, cond_type, values

        operation_str, cond_type, values = parse_hint(current_hint)
        rows = len(current_grid)
        cols = len(current_grid[0]) if rows else 0
        valid_moves = []

        for r in range(1, rows + 1):
            for c in range(1, cols + 1):
                cell_val = current_grid[r-1][c-1]
                if cell_val != 0:
                    continue
                # Compute value based on operation
                if operation_str == 'sum':
                    val = r + c
                elif operation_str == 'product':
                    val = r * c
                elif operation_str == 'difference':
                    val = r - c
                else:
                    raise ValueError('Invalid operation')

                cond_met = False
                if cond_type == 'less than':
                    cond_met = val < values[0]
                elif cond_type == 'greater than':
                    cond_met = val > values[0]
                elif cond_type == 'contains digit':
                    s = str(val)
                    cond_met = str(values[0]) in s
                elif cond_type == 'even':
                    cond_met = val % 2 == 0
                elif cond_type == 'odd':
                    cond_met = val % 2 != 0
                elif cond_type == 'between':
                    v1, v2 = values
                    cond_met = v1 <= val <= v2
                else:
                    raise ValueError('Unknown condition type')

                if cond_met:
                    valid_moves.append((r, c))

        # Check winning moves first
        winning_move = None
        for move in valid_moves:
            r, c = move
            r_idx = r - 1
            c_idx = c - 1
            grid_copy = [row.copy() for row in current_grid]
            grid_copy[r_idx][c_idx] = player_idx
            if player_idx == 1:
                if has_left_right_connection(grid_copy, 1):
                    winning_move = move
                    break
            else:
                if has_top_bottom_connection(grid_copy, 2):
                    winning_move = move
                    break

        if winning_move:
            position_selected = winning_move
        else:
            # Apply heuristic
            center_row_1 = (rows + 1) / 2.0
            center_col_1 = (cols + 1) / 2.0
            candidates = []

            for move in valid_moves:
                r, c = move
                r_idx = r - 1
                c_idx = c - 1
                count = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr = r_idx + dr
                        nc = c_idx + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if current_grid[nr][nc] == player_idx:
                                count += 1
                dr = r - center_row_1
                dc = c - center_col_1
                distance_sq = dr**2 + dc**2
                score = count * 1000 - distance_sq
                candidates.append((score, move))

            sorted_candidates = sorted(candidates, key=lambda x: -x[0])
            position_selected = sorted_candidates[0][1] if sorted_candidates else (1, 1)

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

