                # Compute distance to target edge
                if player_idx == 1:
                    distance = cols - c
                else:
                    distance = rows - r
                return (-int(is_target_edge), -int(adjacent), distance)

            candidates_sorted = sorted(candidates, key=priority_key)
            position_selected = candidates_sorted[0]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

