from collections import deque

class SuperplyCustomStrategy:
    def receive_message(self, message: Info) -> Info:
        current_grid = message.message[0].data[0]
        current_hint = message.message[0].data[1]
        player_idx = message.message[0].data[2]

        def get_condition_func(condition_str):
            import re
            m_less = re.match(r"^is less than (\\d+)$", condition_str)
            if m_less:
                v = int(m_less.group(1))
                return lambda x: x < v
            m_greater = re.match(r"^is greater than (\\d+)$", condition_str)
            if m_greater:
                v = int(m_greater.group(1))
                return lambda x: x > v
            m_contains = re.match(r"^contains digit (\\d+)$", condition_str)
            if m_contains:
                digit = m_contains.group(1)
                return lambda x: str(digit) in str(x)
            if condition_str == "is even":
                return lambda x: x % 2 == 0
            if condition_str == "is odd":
                return lambda x: x % 2 != 0
            m_between = re.match(r"^is between (\\d+) and (\\d+), inclusive$", condition_str)
            if m_between:
                v1 = int(m_between.group(1))
                v2 = int(m_between.group(2))
                return lambda x: v1 <= x <= v2
            else:
                raise ValueError(f"Unrecognized condition: {condition_str}")

        operation_str, condition_str = current_hint.split(' ', 1)
        condition_func = get_condition_func(condition_str)
        N = len(current_grid)
        candidates = []
        for i in range(1, N+1):
            for j in range(1, N+1):
                if current_grid[i-1][j-1] != 0:
                    continue
                if operation_str == 'sum':
                    val = i + j
                elif operation_str == 'product':
                    val = i * j
                elif operation_str == 'difference':
                    val = abs(i - j)
                else:
                    raise ValueError(f"Unknown operation: {operation_str}")
                if condition_func(val):
                    candidates.append((i, j))

        def is_winning_move(grid, player, i, j):
            new_grid = [row.copy() for row in grid]
            new_grid[i-1][j-1] = player
            if player == 1:
                visited = [[False]*N for _ in range(N)]
                q = deque()
                for r in range(N):
                    if new_grid[r][0] == 1:
                        q.append((r, 0))
                        visited[r][0] = True
                while q:
                    r, c = q.popleft()
                    if c == N-1:
                        return True
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if not visited[nr][nc] and new_grid[nr][nc] == 1:
                                    visited[nr][nc] = True
                                    q.append((nr, nc))
                return False
            else:
                visited = [[False]*N for _ in range(N)]
                q = deque()
                for c in range(N):
                    if new_grid[0][c] == 2:
                        q.append((0, c))
                        visited[0][c] = True
                while q:
                    r, c = q.popleft()
                    if r == N-1:
                        return True
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < N and 0 <= nc < N:
                                if not visited[nr][nc] and new_grid[nr][nc] == 2:
                                    visited[nr][nc] = True
                                    q.append((nr, nc))
                return False

        winning_candidates = []
        for (i,j) in candidates:
            if is_winning_move(current_grid, player_idx, i, j):
                winning_candidates.append((i,j))
        if winning_candidates:
            best_i, best_j = winning_candidates[0]
        else:
            def compute_priority(i,j):
                score = 0
                if player_idx == 1:
                    if j == 1 or j == N:
                        score += 100
                elif player_idx == 2:
