                        ni, nj = i + di, j + dj
                        if 1 <= ni <= N and 1 <= nj <= N:
                            if current_grid[ni-1][nj-1] == player_idx:
                                count += 1
                score += count * 10
                # Distance to center
                cx = (N // 2) + 1
                cy = (N // 2) + 1
                dx = i - cx
                dy = j - cy
                dist_sq = dx*dx + dy*dy
                score -= dist_sq
                return score

            scored = []
            for (i,j) in candidates:
                s = compute_priority(i,j)
                scored.append( (s, i, j) )
            # Sort in descending order of score
            scored.sort(key=lambda x: -x[0])
            best_i, best_j = scored[0][1], scored[0][2]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.receiver,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=(best_i, best_j), type='custom')]
        )

